import random


def first_default_mc(rates, years, trials, seed):
    # share of trials in which at least one name defaults within `years`
    rng = random.Random(seed)
    hits = 0
    for _ in range(trials):
        if min(rng.expovariate(r) for r in rates) <= years:
            hits += 1
    return hits / trials
